@ExtendWith(MockitoExtension.class)
class PaymentServiceTest {
    @Mock
    private RestTemplate restTemplate;
    private PaymentService paymentService;

    @BeforeEach
    void setUp() {
        paymentService = new PaymentService(restTemplate);
    }

    @Test
    void processPayment_callsExternalAPIAndReturnsStatus() {
        var request = new PaymentRequest("txn-123", 99.99);
        var apiResponse = new PaymentAPIResponse("SUCCESS", "txn-123");
        // Stub the external API call
        when(restTemplate.postForObject(
            "https://payment-gateway.com/api/charge",
            request,
            PaymentAPIResponse.class
        )).thenReturn(apiResponse);

        var result = paymentService.processPayment(request);

        assertEquals("SUCCESS", result.getStatus());
        verify(restTemplate).postForObject(anyString(), eq(request), eq(PaymentAPIResponse.class));
    }
}
